css:
/* ==== Track Diagram: the Phosphor Interface drawn as a signal box's illuminated diagram ====
   Faces with one job each: Archivo, narrowed, for the panel's engraved legends (titles, section
   heads, day numerals); DM Sans for what people and Vera say; DM Mono for the machine's stamps
   (times, dates, counts), in tabular figures; VT323 on the tubes only.
   Materials with one job each: green-black slate boards (trays) that the diagram is painted on,
   raised slate plates for what the family keeps, green-black glass for the machine.
   The lamp legend, on every page: a hollow ring is to come, lit sage is done, amber needs a
   look, a red ring is off, and #6dff9c is lit only for now and live. */

:root {
  /* The page-wide roles, as properties the sheet can use (the theme writes them as values). */
  --steel: #a7c4d8;
  --heading: #ebe6da;
  --label: #a3b3bf;
  --bubble: #111712;
  --bubble-them: #1c252b;
  --tray: #0f1519;
  --tray-edge: #182026;
  --plate: var(--surface);
  --plate-edge: #262e35;
  --rail: #394652;
  --rail-hi: #58697a;
  --sq: 4px;
  --lamp: 12px;
  --head: "Archivo", var(--sans);
  --lift: 0 1px 0 rgb(0 0 0 / 0.55), 0 10px 22px -18px rgb(0 0 0 / 0.9);
  --shadow: 0 1px 0 rgb(0 0 0 / 0.5);
  --r-xl: 16px;
  --r-lg: 6px;
  --r: 6px;
  --r-sm: 5px;
}
html { scrollbar-color: #3a454f var(--bg); }
body { font-kerning: normal; font-variant-numeric: tabular-nums; }

/* ---- Type: three steps of legend, one of reading, one of stamp ---------------------------- */
h1, h2, .h2, .month-head h2, .step-head h1, .signin h1, .lost h1 {
  font-family: var(--head);
  font-stretch: 84%;
  word-spacing: 0.08em;
  font-optical-sizing: auto;
  color: var(--heading);
}
.page-head h1 { font-size: clamp(2.3rem, 4.4vw, 3.05rem); font-weight: 700; line-height: 1; letter-spacing: -0.012em; }
h2, .h2, .section-head h2, .panel > h2, .panel > summary .h2 { font-size: 1.42rem; font-weight: 650; line-height: 1.15; letter-spacing: -0.006em; }
.card h2, .task h2 { font-family: var(--sans); font-stretch: 100%; font-size: 1.04rem; font-weight: 600; letter-spacing: -0.005em; line-height: 1.3; }
.month-head h2 { font-size: 1.7rem; font-weight: 700; letter-spacing: -0.01em; }
.stamp, .hang, .rel, .said-by, .eyebrow, .chip-mon, .chip-dow, .card-id, .count, .facts .at, .legal, h3, .data caption, table.month th {
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
}
.stamp, .hang { font-size: 0.75rem; font-weight: 500; line-height: 1.3; letter-spacing: 0; text-transform: none; white-space: nowrap; color: var(--label); }
.stamp .t { color: var(--ink); }
.stamp.window { white-space: normal; text-wrap: balance; }
.due-word { display: none; }
/* A timetable's margin is named once, at its head, in the legend's tracked caps. */
.margin-legend { margin: -0.3rem 0 0.35rem; width: calc(var(--m) - 0.2rem); text-align: right; line-height: 1; }
.margin-legend .stamp { font-size: 0.72rem; letter-spacing: 0.05em; text-transform: uppercase; }
.eyebrow, h3, .data caption, table.month th { font-size: 0.74rem; font-weight: 500; letter-spacing: 0.05em; }
.rel { padding: 0; font-size: 0.76rem; font-weight: 500; letter-spacing: 0.02em; color: var(--label); background: none; border-radius: 0; }
.lede { grid-area: l; max-width: 56ch; margin: 0.8rem 0 0; font-size: 1.06rem; line-height: 1.5; color: var(--ink-2); text-wrap: pretty; }
p, li, .said-text { text-wrap: pretty; }
.muted { color: var(--dim); }

/* ---- Links, buttons, controls -------------------------------------------------------------- */
a { text-decoration-thickness: 1px; text-underline-offset: 0.2em; }
button, .button { border-radius: var(--r-sm); }
.button.secondary, button.quiet, .button.ghost { border-radius: var(--r-sm); }
.starters a { border-radius: var(--r-sm); background: color-mix(in srgb, var(--secondary) 5%, transparent); }
input:not([type=checkbox]):not([type=radio]), textarea, select { border-radius: var(--r-sm); }
:focus-visible, input:is([type=checkbox], [type=radio]):focus-visible, select:open, select:focus-visible { outline: 2px solid var(--brand); outline-offset: 2px; border-radius: 4px; }
/* A box to tick: a square well drawn at 1.15rem inside a 2.75rem target a thumb can find. */
input[type=checkbox] {
  --cb-fill: #1a2126; --cb-edge: #5d6873;
  appearance: none; display: inline-grid; place-items: center; flex: none;
  width: 2.75rem; height: 2.75rem; margin: -0.8rem -0.35rem -0.8rem -0.8rem; padding: 0;
  background:
    linear-gradient(var(--cb-fill), var(--cb-fill)) center / calc(1.15rem - 3px) calc(1.15rem - 3px) no-repeat,
    linear-gradient(var(--cb-edge), var(--cb-edge)) center / 1.15rem 1.15rem no-repeat;
  border: 0; border-radius: 0; cursor: pointer;
  vertical-align: middle;
}
input[type=checkbox]::before { content: ""; width: .28rem; height: .56rem; margin-top: -.12rem; border: solid var(--on-bright); border-width: 0 2px 2px 0; rotate: 45deg; scale: 0; transition: scale .12s; }
input[type=checkbox]:hover { --cb-edge: var(--lit); }
input[type=checkbox]:checked { --cb-fill: var(--lit); --cb-edge: var(--lit); }
input[type=checkbox]:checked::before { scale: 1; }
input[type=checkbox]:focus, input[type=checkbox]:focus-visible { box-shadow: none; }
input[type=checkbox]:focus-visible { outline-offset: calc(-0.8rem + 3px); border-radius: 0; }
input[type=radio] { accent-color: var(--lit); }
@supports (appearance: base-select) {
  select, ::picker(select) { appearance: base-select; }
  select { align-items: center; padding-block: 0; }
  select::picker-icon { content: none; }
  ::picker(select) { margin-top: .3rem; padding: .3rem; background: var(--surface-2); border: 1px solid var(--plate-edge); border-radius: var(--r); box-shadow: 0 18px 36px -18px #000; }
  select option { min-height: 2.5rem; padding-inline: .6rem; border-radius: 3px; }
  select option:hover, select option:focus-visible { background: var(--surface-3); }
  select option::checkmark { color: var(--lit); }
}
label:has(> input[type=checkbox]) { min-height: 2.75rem; }

/* ---- The bar: its rule is a track; where you are is a lamp on it --------------------------- */
.bar { border-bottom: 2px solid #212a30; }
.places a, .tools > a, .menu > summary { position: relative; }
:is(.places a, .tools > a)[aria-current], .menu.here > summary { color: var(--heading); background: color-mix(in srgb, var(--steel) 16%, #111820); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--steel) 42%, transparent); }
:is(.places a, .tools > a)[aria-current] .icon, .menu.here > summary .icon { filter: none; }
:is(.places a, .tools > a)[aria-current]::before, .menu.here > summary::before {
  content: "";
  position: absolute;
  left: calc(50% - 1.5rem);
  bottom: calc(-0.55rem - 1px - 5.5px);
  width: 3rem;
  height: 11px;
  border: 0;
  transform: none;
  background:
    radial-gradient(circle at 50% 50%, var(--steel) 0 3.5px, #0f1418 3.6px 5.5px, transparent 5.6px),
    linear-gradient(var(--steel), var(--steel)) 50% 50% / 100% 2px no-repeat;
  pointer-events: none;
}
.menu.here > summary::before { margin: 0; }
.places a, .tools > a, .menu > summary, .brand, .menu-list a, .signout button.quiet, .ask .who select { min-height: 2.75rem; }
.tools > a, .menu > summary { min-width: 2.75rem; justify-content: center; }
.starters a { min-height: 2.75rem !important; }
.setup > p a, .agenda .what a, .kid-plates a, .card h2 a, .crumbs a { padding: 0.8rem 0.3rem; margin: -0.8rem -0.3rem; }
.section-head a { min-width: 2.75rem; justify-content: center; }
/* Every inline link in running text reaches 44px without moving a line: padding on an inline
   box widens what takes the tap, never the line it sits in. */
.spend p > a, .page-status p > a, .page-status li > a, main > p > a, .said-text a { padding: 0.85rem 0.2rem; margin: -0.85rem -0.2rem; }
.event a { padding: 0.95rem 0.2rem; margin: -0.95rem -0.2rem; }
.crt .on-radar-line a { padding-block: 0.75rem; background-clip: content-box; }
.field.can-dictate > button.mic, button.mic { width: 2.75rem; height: 2.75rem; min-height: 2.75rem; }
.field.can-dictate > button.mic { right: 0.15rem; bottom: 0.15rem; }
details > summary { min-height: 2.75rem; }
.crumbs a { padding-block: 0.95rem; }
.kids-talk ul.plain { display: grid; grid-template-columns: repeat(auto-fill, minmax(12rem, 1fr)); gap: 0.5rem; }
.kids-talk ul.plain > li { padding: 0; border: 0; }
.kids-talk li a { display: flex; align-items: center; min-height: 2.75rem; padding: 0.5rem 0.9rem; color: var(--heading); text-decoration: none; background: var(--plate); border: 1px solid var(--plate-edge); border-left: 3px solid var(--pink); border-radius: var(--sq); }
.kids-talk li a:hover { background: var(--surface-2); }
@media (max-width: 51.99rem) {
  .places { border-top: 2px solid #212a30; background: color-mix(in srgb, #0f1519 94%, transparent); }
  .places a[aria-current] { background: none; color: var(--heading); }
  .places a[aria-current="page"] .icon { background: color-mix(in srgb, var(--steel) 18%, #141b20); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--steel) 45%, transparent); }
  .places a[aria-current]::before { top: calc(-0.4rem - 2px - 4.5px); bottom: auto; }
}

/* ---- The masthead: a ring, a drop, a corner, and the rule the title stands on -------------- */
.page-head {
  position: relative;
  display: grid;
  grid-template-columns: 2.75rem minmax(0, 1fr) auto;
  grid-template-areas: "c c c" "r t a" ". l l";
  gap: 0 1rem;
  align-items: end;
  margin: 0 0 2rem;
}
.page-head::before { content: ""; grid-column: 2 / -1; grid-row: 2; align-self: end; height: 2px; background: var(--rail); }
.crumbs { grid-area: c; margin: 0 0 0.9rem; }
.rail { grid-area: r; align-self: stretch; display: flex; flex-direction: column; align-items: center; }
.rail::after {
  content: "";
  flex: 1;
  align-self: flex-end;
  width: calc(50% + 1rem + 1px);
  min-height: 0.7rem;
  margin: 0.3rem -1rem 0 0;
  border: solid var(--rail);
  border-width: 0 0 2px 2px;
  border-bottom-left-radius: 10px;
}
.title-icon, .title-icon.presence {
  width: 2.75rem; height: 2.75rem;
  color: var(--accent);
  background: var(--bg);
  border: 2px solid var(--steel);
  border-radius: 50%;
  box-shadow: none;
}
.title-icon.presence { border-color: color-mix(in srgb, var(--brand) 55%, var(--rail)); }
.title-icon .icon { width: 1.3rem; height: 1.3rem; filter: none; }
.page-title { grid-area: t; min-width: 0; padding: 0 0 0.8rem; }
.page-actions { grid-area: a; align-self: end; display: flex; flex-wrap: wrap; justify-content: flex-end; gap: 0.6rem; padding: 0 0 0.75rem; }
.page-actions .tabs { margin: 0; }
@media (max-width: 40rem) {
  .page-head { grid-template-columns: 2.4rem minmax(0, 1fr); grid-template-areas: "c c" "r t" ". l" ". a"; column-gap: 0.75rem; }
  .title-icon, .title-icon.presence { width: 2.4rem; height: 2.4rem; }
  .rail::after { width: calc(50% + 0.75rem + 1px); margin-right: -0.75rem; }
  .page-actions { justify-content: flex-start; padding: 0.75rem 0 0; }
}

/* ---- Boards and plates --------------------------------------------------------------------- */
.tray, .panel.tray {
  margin: 0 0 1.5rem;
  padding: 1.1rem 1.25rem 1.3rem;
  background: var(--tray);
  border: 1px solid var(--tray-edge);
  border-radius: var(--sq);
  box-shadow: none;
}
.panel { border-radius: var(--sq); }
:is(form.panel, details.panel, .panel:has(.setting, form), .ask) { border: 1px solid var(--plate-edge); box-shadow: var(--lift); }
.section-head { align-items: center; margin: 0 0 1rem; }
.section-head h2, .panel > h2 { display: flex; align-items: center; gap: 0.7rem; margin: 0; }
.panel:not(.card) > h2 { margin: 0 0 1rem; }
.section-head a { margin-block: -0.5rem; padding: 0.55rem 0.1rem; min-height: 2.75rem; font-size: 0.92rem; font-weight: 500; color: var(--steel); text-decoration: underline; text-decoration-color: color-mix(in srgb, currentColor 35%, transparent); }
.section-head a:hover { color: var(--heading); text-decoration-color: currentColor; }
.section-links { gap: 0 1.25rem; }
/* A head's icon sits in a 1.95rem cell so every head's icon stands over the same column. Only a
   terminus, a head a line actually leaves from, draws the ring round it; elsewhere the icon is
   bare, in its section's colour. */
.ring {
  display: inline-grid; place-items: center; flex: none;
  width: 1.95rem; height: 1.95rem;
  color: var(--rk, var(--steel));
  background: none;
  border: 1.5px solid transparent;
  border-radius: 50%;
}
h2 .ring .icon, .ring .icon { width: 1.12rem; height: 1.12rem; stroke-width: 1.9; color: inherit; }
.lately .section-head .ring, .monitors > .tray:first-child .ring { background: var(--tray); border-color: var(--rail-hi); }
:is(.lately .section-head, .monitors > .tray:first-child) .ring .icon { width: 0.95rem; height: 0.95rem; stroke-width: 2; }
.ring .glyph.presence { width: 1rem; height: 1rem; border-radius: 50%; }
.coming { --rk: var(--cyan); --lc: var(--cyan); }
.home-todo { --rk: var(--lemon); --lc: var(--lemon); }
.lately { --rk: var(--lilac); }
.kids { --rk: var(--pink); --lc: var(--pink); }
.setup { --rk: var(--amber); --lc: var(--amber); }

/* A line: lamps on a painted rail, a plate beside each; the rail runs from the first lamp to
   the last and no further. --m is the timetable margin, --rx the rail, --px the plates. */
.line {
  --m: 0rem;
  --rx: calc(var(--m) + 0.45rem);
  --px: calc(var(--rx) + 1.25rem);
  --ly: 1.4rem;
  --gap: 0.5rem;
  position: relative;
  display: grid;
  gap: var(--gap);
  margin: 0;
  padding: 0 0 0 var(--px);
  list-style: none;
}
.line > li { position: relative; margin: 0; }
.line > li::before {
  content: "";
  position: absolute;
  z-index: 2;
  left: calc(var(--rx) - var(--px) - var(--lamp) / 2);
  top: calc(var(--ly) - var(--lamp) / 2);
  width: var(--lamp); height: var(--lamp);
  box-sizing: border-box;
  background: var(--tray);
  border: 2px solid var(--lc, var(--rail-hi));
  border-radius: 50%;
  transition: border-color var(--afterglow), box-shadow var(--afterglow), background-color var(--afterglow);
}
.line > li:not(:last-child)::after {
  content: "";
  position: absolute;
  z-index: 1;
  left: calc(var(--rx) - var(--px) - 1px);
  top: var(--ly);
  width: 2px;
  height: calc(100% + var(--gap));
  background: var(--rail);
}
.line > li.empty::before, .line > li.empty::after { content: none; }
.hang {
  position: absolute;
  left: calc(-1 * var(--px));
  top: calc(var(--ly) - 0.5lh);
  width: calc(var(--m) - 0.2rem);
  text-align: right;
}
.hang .stamp { display: block; }
.hang .warn, .stamp.warn { color: var(--amber); }

/* A plate: what the family keeps, square, raised off the board; it answers the pointer and its
   light fades like a tube's. */
.plate, .checklist > li, .agenda-body, .lately .idea-card, .kid-plates > li, .lights > li, .task-line > li.task {
  background: var(--plate);
  border: 1px solid var(--plate-edge);
  border-radius: var(--sq);
  box-shadow: var(--shadow);
  transition: background-color var(--afterglow), border-color var(--afterglow), box-shadow var(--afterglow);
}
:is(.checklist > li, .lately .idea-card, .kid-plates > li, .across > li, .plan-line .line > li, .task-line > li.task):hover {
  transition-duration: var(--glow-in);
}
:is(.checklist > li, .lately .idea-card, .kid-plates > li:has(a), .task-line > li.task):hover,
.across > li:hover .agenda-body, .plan-line .line > li:hover {
  background: var(--surface-2);
  border-color: color-mix(in srgb, var(--lc, var(--steel)) 50%, var(--plate-edge));
  box-shadow: var(--shadow), 0 0 32px -12px color-mix(in srgb, var(--lc, var(--steel)) 55%, transparent);
}
.line > li:hover::before { border-color: var(--heading); transition-duration: var(--glow-in); }

/* ---- Home: the greeting stays lit glass --------------------------------------------------- */
.welcome { border-radius: var(--r-xl); background-color: #101611; border-color: #1c241f; }
.welcome .ask { border-radius: 8px; border-color: color-mix(in srgb, var(--brand) 38%, var(--line-2)); }
.ask { border-radius: 8px; }
.ask .locate .icon { color: var(--steel); }
.ask-question { font-family: var(--sans); font-stretch: 100%; font-weight: 650; letter-spacing: -0.02em; color: var(--heading); }
.ask .who label, .ask .who .from { font: 500 0.875rem/1 var(--sans); color: var(--ink-2); }
/* Send is always the last thing on the From row, after the mic, on Home as in the chat. */
.ask-bar { gap: 0.6rem 0.75rem; }
.ask .who { flex: 0 1 auto; min-width: 0; }
.ask .who select { min-width: 0; max-width: 100%; }
@media (max-width: 40rem) {
  .ask .who { flex: 1 1 0; }
  .ask .who select { flex: 1 1 auto; width: 100%; }
  /* Home's box is narrower: its "From" is read out, and the picker's own words say who. */
  .welcome .ask .who > label { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  .kids-talk.tray { margin-top: 1.75rem; }
}
.speaker .eyebrow { color: var(--label); }
.brief-more a { color: var(--steel); }

/* Next up in a thin, square case: a fine groove round the glass, vents and a lamp in the chin. */
.crt {
  padding: 0.5rem 0.5rem 1.6rem;
  background: linear-gradient(180deg, #474d53, #3a3f45 38%, #30353a);
  border: 1px solid #52595f;
  border-radius: 8px;
  box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.13), inset 0 -1px 0 rgb(0 0 0 / 0.45), 0 1px 0 rgb(0 0 0 / 0.6), 0 26px 40px -30px #000;
}
.crt-tube { border-radius: 5px / 7px; box-shadow: 0 0 0 1px #111417, 0 0 0 2.5px #565d64, inset 0 0 0 1.5px #020403, inset 0 0 36px 6px rgb(0 0 0 / 0.72); }
.crt::before {
  content: "";
  position: absolute;
  left: 0.85rem;
  bottom: 0.58rem;
  width: 3.3rem;
  height: 0.42rem;
  background: repeating-linear-gradient(90deg, #1b1f23 0 2px, transparent 2px 5px);
  border-radius: 1px;
  box-shadow: 0 1px 0 rgb(255 255 255 / 0.06);
}
.crt::after { right: 0.95rem; bottom: 0.62rem; width: 0.36rem; height: 0.36rem; background: var(--brand); box-shadow: 0 0 0 1.5px #22262a, 0 0 6px var(--brand); }
.next-up .next-more { white-space: nowrap; }
.next-up .next-more a, .next-up .next-title a { padding-block: 0.8rem; background-clip: content-box; }
.on-radar .rel { white-space: nowrap; }

/* The setup steps: a short line of amber rings, each a step that needs a look. */
.setup.setup { background: #131612; border: 1px solid #644e29; border-radius: var(--sq); box-shadow: none; }
.setup .line { --rx: 0.85rem; --px: 2.1rem; --ly: 1.25rem; --gap: 0rem; gap: var(--gap); padding-left: var(--px); }
.setup li { display: block; }
.setup li a { display: inline-block; padding-block: 0.62rem; }
.setup li::before { transform: none; }
.setup > p { margin: 0.6rem 0 0; }
/* Wide enough, the steps run across like the main line: a lamp each, the rail between them. */
@media (min-width: 52rem) {
  .setup .line { --gap: 1.5rem; grid-template-columns: repeat(auto-fit, minmax(13rem, 1fr)); padding: 0; }
  .setup .line > li { padding-top: 1.35rem; }
  .setup .line > li::before { left: 0; top: 0; }
  .setup .line > li:not(:last-child)::after { left: var(--lamp); top: calc(var(--lamp) / 2 - 1px); width: calc(100% + var(--gap) - var(--lamp)); height: 2px; }
  .setup li a { padding-block: 0.3rem; }
  .setup > p { margin-top: 0.9rem; }
}

/* Coming up: the main line, across the board, from the lit now lamp to the last stop. */
.coming .source { margin: -0.3rem 0 1rem; }
.board { display: flex; align-items: center; gap: 0.85rem; }
.chip { display: grid; grid-template: "d m" "d w" / auto auto; column-gap: 0.45rem; align-items: center; justify-items: start; width: auto; padding: 0; background: none; border: 0; border-radius: 0; box-shadow: none; }
.chip-day { grid-area: d; margin: 0; font-family: var(--head); font-stretch: 84%; font-size: 1.9rem; font-weight: 700; line-height: 0.9; letter-spacing: -0.01em; color: var(--heading); }
.chip-mon { grid-area: m; font-size: 0.7rem; font-weight: 500; line-height: 1.15; letter-spacing: 0.05em; color: var(--cyan); }
.chip-dow { grid-area: w; font-size: 0.7rem; font-weight: 500; line-height: 1.15; letter-spacing: 0.05em; text-transform: uppercase; color: var(--label); }
.chip.is-today { box-shadow: none; }
.chip.is-today .chip-day { color: var(--heading); }
.agenda .what { font-size: 1rem; font-weight: 600; line-height: 1.3; color: var(--heading); }
.agenda .what a { color: var(--heading); text-decoration: none; }
.agenda .what a::after { content: ""; position: absolute; inset: 0; }
.agenda .when { margin-top: 0.15rem; font-size: 0.875rem; color: var(--ink-2); }
.agenda .when .t { font: 500 0.82rem/1.3 var(--mono); font-variant-numeric: tabular-nums; color: var(--ink-2); }
.agenda > li { display: block; }
.agenda-body { position: static; padding: 0.65rem 0.85rem 0.7rem; }
.across > li { position: relative; }
@media (min-width: 40rem) {
  .across { --by: 3.35rem; display: flex; gap: 0.9rem; padding: 0 0 0 2.4rem; }
  .across > li { flex: 1 1 0; min-width: 11.5rem; max-width: 19rem; display: grid; grid-template-columns: minmax(0, 1fr); grid-template-rows: 2.3rem auto; row-gap: 1.95rem; align-items: start; }
  .across > li::before { left: 0.95rem; top: calc(var(--by) - var(--lamp) / 2); border-color: var(--cyan); }
  .across > li:not(:last-child)::after { left: 0.95rem; top: calc(var(--by) - 1px); width: calc(100% + 0.9rem); height: 2px; }
  .across::before {
    content: ""; position: absolute; z-index: 2; left: 0; top: calc(3.35rem - 7px);
    width: 14px; height: 14px; border-radius: 50%;
    background: var(--brand); box-shadow: 0 0 0 3px var(--tray), 0 0 10px var(--brand);
    animation: breathe 3.2s ease-in-out infinite;
  }
  .across::after { content: ""; position: absolute; z-index: 1; left: 7px; top: calc(3.35rem - 1px); width: calc(2.4rem + 0.95rem - 7px); height: 2px; background: var(--rail); }
  .across .board { padding: 0 0 0 0.35rem; }
  .across .agenda-body { position: relative; }
  .across .agenda-body::before { content: ""; position: absolute; left: calc(0.95rem - 0.5px); top: calc(var(--by) - 4.25rem + var(--lamp) / 2); height: calc(4.25rem - var(--by) - var(--lamp) / 2); width: 1px; background: var(--rail-hi); }
}
@media (max-width: 39.99rem) {
  .across { --m: 4.1rem; --ly: 1.25rem; }
  .across .board { position: absolute; left: calc(-1 * var(--px)); top: 0.35rem; width: calc(var(--m) - 0.25rem); flex-direction: column; align-items: flex-end; gap: 0.2rem; }
  .across .rel { font-size: 0.72rem; }
  .across::before { content: ""; position: absolute; z-index: 2; left: calc(var(--rx) - 7px); top: -1.3rem; width: 14px; height: 14px; border-radius: 50%; background: var(--brand); box-shadow: 0 0 0 3px var(--tray), 0 0 10px var(--brand); }
  .across::after { content: ""; position: absolute; left: calc(var(--rx) - 1px); top: -1.3rem; height: 2.5rem; width: 2px; background: var(--rail); }
  .coming .source { margin-bottom: 2rem; }
}

/* The dashboard: To do and the kids' lists on the left, the newest ideas on the right. */
.dashboard { gap: 0 1.5rem; }
@media (min-width: 52rem) { .dashboard { grid-template-columns: minmax(0, 1.22fr) minmax(0, 1fr); align-items: start; } }

/* To do: a timetable. The day hangs in the margin, the lamp is the stop, the plate holds the box
   to tick, the title, and the time and who in a column read straight down. */
.home-todo { --m: 7rem; }
.checklist { --m: 7rem; --rx: calc(var(--m) + 0.6rem); --px: calc(var(--rx) + 1.15rem); --ly: 1.45rem; }
.checklist > li { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 0 0.55rem; min-height: 2.9rem; padding: 0.2rem 0.8rem 0.2rem 0.3rem; }
.checklist > li::before { border-color: color-mix(in srgb, var(--lemon) 70%, var(--rail-hi)); }
.checklist > li.late::before { background: var(--amber); border-color: var(--amber); box-shadow: 0 0 0 3px var(--tray); }
.checklist > li:not(.timed)::before { border-color: var(--rail-hi); }
.checklist .what { font-size: 1rem; font-weight: 600; line-height: 1.3; color: var(--heading); }
.checklist .when { margin: 0.1rem 0 0; font-size: 0.85rem; }
.checklist .facts { display: flex; align-items: baseline; gap: 0.5rem; margin: 0; font-size: 0.85rem; line-height: 1.25; color: var(--ink-2); white-space: nowrap; }
.facts .at { font-size: 0.8rem; font-weight: 500; color: var(--ink); }
.facts .who { color: var(--dim); }
.checklist > li.empty { display: flex; margin-left: calc(-1 * var(--px)); background: none; border: 0; box-shadow: none; }
/* The box to tick is square, a control, never a lamp; the lamp is on the line. */
button.tick { width: 2.75rem; height: 2.75rem; margin: -0.2rem 0; border-radius: var(--r-sm); }
button.tick::before { width: 1.15rem; height: 1.15rem; background: #1a2126; border: 1.5px solid #5d6873; border-radius: 3px; }
button.tick .icon { width: 0.8rem; height: 0.8rem; }
button.tick:hover { color: var(--on-bright); }
button.tick:hover::before { background: color-mix(in srgb, var(--lit) 30%, #1a2126); border-color: var(--lit); box-shadow: 0 0 12px -4px var(--lit); }
button.tick:active::before { background: var(--lit); border-color: var(--lit); }
.late .what { color: var(--heading); }

/* The kids' lists, a stop each with the gift ring for its lamp. */
.kid-plates { --rx: 0.975rem; --px: 2.6rem; --ly: 1.4rem; }
.kid-plates > li::after { content: none !important; }
.kid-plates > li { display: flex; flex-wrap: wrap; align-items: baseline; gap: 0.2rem 0.75rem; padding: 0.6rem 0.9rem !important; border-bottom: 1px solid var(--plate-edge) !important; }
.kid-plates > li::before { content: none; }
.kid-lamp {
  position: absolute; z-index: 2;
  left: calc(var(--rx) - var(--px) - 0.95rem); top: calc(var(--ly) - 0.95rem);
  display: grid; place-items: center; width: 1.9rem; height: 1.9rem;
  color: var(--pink); background: var(--tray); border: 1.5px solid color-mix(in srgb, var(--pink) 55%, var(--rail-hi)); border-radius: 50%;
}
.kid-lamp .icon { width: 0.9rem; height: 0.9rem; }
.kid-plates a { color: var(--heading); text-decoration: none; }
.kid-plates a::after { content: ""; position: absolute; inset: 0; }
.kid-plates a strong { font-weight: 600; }
.kid-top { color: var(--ink-2); font-size: 0.9rem; }
.count-open { margin-left: auto; font: 500 0.85rem/1.3 var(--sans); font-variant-numeric: tabular-nums; color: var(--label); }

/* Lately added: newest first, each kind's ring the lamp, each plate tinted with its kind. */
.lately .idea-cards { position: relative; --rx: 0.975rem; --px: 2.6rem; --ly: 1.45rem; --gap: 0.5rem; display: grid; grid-template-columns: minmax(0, 1fr); gap: var(--gap); margin: 0 0 1rem; }
.lately .idea-card { --tint: 9%; position: relative; display: grid; gap: 0.15rem; padding: 0.55rem 0.9rem 0.6rem; background: color-mix(in srgb, var(--accent) var(--tint), var(--plate)); transform: none; }
.lately .idea-card:has(.kind-restaurant, .kind-activity, .kind-seasonal) { --tint: 5%; }
.lately .idea-card::before { content: none; }
/* A terminus: the head's ring, and the line dropping from it through the head to the first stop,
   however the head wraps. */
:is(.lately, .monitors > .tray:first-child) > .section-head { position: relative; }
:is(.lately, .monitors > .tray:first-child) > .section-head::after { content: ""; position: absolute; left: calc(0.975rem - 1px); top: 1.95rem; bottom: -1rem; width: 2px; background: var(--rail); }
.lately .idea-cards::before { content: ""; position: absolute; z-index: 1; left: calc(var(--rx) - 1px); top: 0; width: 2px; height: calc(var(--ly) - 0.95rem); background: var(--rail); }
@media (max-width: 40rem) { .lately .section-links { margin-left: 2.6rem; } }
.lately .idea-card:not(:last-child)::after { content: ""; position: absolute; z-index: 1; left: calc(var(--rx) - var(--px) - 1px); top: var(--ly); width: 2px; height: calc(100% + var(--gap)); background: var(--rail); }
.lately .idea-card:hover { background: color-mix(in srgb, var(--accent) calc(var(--tint) + 5%), var(--surface-2)); border-color: color-mix(in srgb, var(--accent) 55%, var(--plate-edge)); box-shadow: var(--shadow), 0 0 32px -12px color-mix(in srgb, var(--accent) 55%, transparent); transform: none; }
.lately .kind .icon { transition: border-color var(--afterglow), box-shadow var(--afterglow); }
.lately .idea-card:hover .kind .icon { border-color: var(--kind); box-shadow: 0 0 10px -3px var(--kind); transition-duration: var(--glow-in); }
.lately .idea-card strong { font-size: 1rem; font-weight: 600; line-height: 1.3; color: var(--heading); }
.idea-facts { display: flex; flex-wrap: wrap; align-items: baseline; gap: 0 0.7rem; font-size: 0.875rem; }
.idea-facts .muted { font-size: 0.875rem; }
.lately .kind { font-size: 0.8rem; font-weight: 600; }
.lately .kind .icon, .cards .card .kind .icon {
  position: absolute; z-index: 2;
  box-sizing: border-box; width: 1.9rem; height: 1.9rem; padding: 0.42rem;
  color: var(--kind); background: var(--tray);
  border: 1.5px solid color-mix(in srgb, var(--kind) 55%, var(--rail-hi)); border-radius: 50%;
  stroke-width: 2;
}
.lately .kind .icon { left: calc(var(--rx) - var(--px) - 0.95rem); top: calc(var(--ly) - 0.95rem); }
.restaurants-link.panel { margin: 0; padding: 0.8rem 1rem; border-radius: var(--sq); background: #131612; border: 1px solid #644e29; box-shadow: none; }
.restaurants-icon { border-radius: var(--sq); width: 2.6rem; height: 2.6rem; }
.restaurants-link strong { font-size: 1.05rem; }

/* ---- Chat: the line hangs from her screen and ends at the box ---------------------------- */
/* Her lines leave the track from her screen, their time in the margin beside it. The family's
   arrive at a steel ring on the track and are read along a dotted leader, as a timetable is:
   ring, leader, the time, then the words, flush right. The day is named once. */
.in-chat main { max-width: 56rem; }
.in-chat { --cm: 4.1rem; --cx: calc(var(--cm) + 1.45rem); }
@media (min-width: 40.01rem) {
  .in-chat .page-head { grid-template-columns: calc(var(--cx) + 1.375rem) minmax(0, 1fr) auto; margin-bottom: 0; }
  .in-chat .page-head::before { content: none; }
  .in-chat .rail { grid-row: 2 / 4; align-items: flex-end; }
  .in-chat .rail::after { width: 0; margin: 0.3rem calc(1.375rem - 1px) -1px 0; border-width: 0 0 0 2px; border-radius: 0; }
  .in-chat .page-title { padding-bottom: 0; }
  .in-chat .lede { margin: 0.5rem 0 0; padding-bottom: 1.8rem; }
  .thread.line { --m: var(--cm); --rx: var(--cx); --px: calc(var(--cx) + 1.6rem); --ly: 1.1rem; --gap: 1.1rem; margin: 0; padding-top: 0.4rem; padding-bottom: 0; }
  .thread.line::before { content: ""; position: absolute; left: calc(var(--rx) - 1px); top: 0; bottom: 0; width: 2px; background: var(--rail); }
  .thread.line > li::after { content: none; }
  .thread.line > li { display: flex; align-items: flex-start; gap: 0.7rem; max-width: none; }
  .thread.line > li::before { content: none; }
  .thread.line .said-when { display: none; }
  .thread.line .hang { top: 0.72rem; }
  .thread.line .said-bot > .avatar { position: absolute; z-index: 2; left: calc(var(--rx) - var(--px) - 1.1rem); top: 0; box-shadow: 0 0 0 4px var(--bg); border-radius: 50%; }
  .thread.line .said-bot .bubble { margin-right: 3rem; }
  .thread.line .said-them { flex-direction: row-reverse; }
  .thread.line .said-them::before { content: ""; left: calc(var(--rx) - var(--px) - 6px); top: calc(var(--ly) - 6px); border-color: var(--steel); }
  .thread.line .said-them::after {
    content: ""; position: absolute; z-index: 0; display: block;
    left: calc(var(--rx) - var(--px) + 6px); right: 5rem; top: var(--ly); height: 1px; width: auto;
    background: repeating-linear-gradient(90deg, var(--rail-hi) 0 1px, transparent 1px 5px);
  }
  .thread.line .said-them > .avatar { order: 0; }
  .thread.line .said-them > .bubble { order: 1; position: relative; z-index: 1; }
  .thread.line .said-them > .hang { order: 2; position: relative; z-index: 1; left: auto; top: auto; width: auto; margin: calc(var(--ly) - 0.5lh) -0.7rem 0 0; padding: 0 0.6rem 0 0.5rem; background: var(--bg); text-align: left; }
  .thread.line .said-them > .hang .stamp { color: var(--ink-2); }
  .thread.line .day-mark { height: 1.1rem; margin-bottom: -0.4rem; }
  .thread.line .day-mark .hang { top: 0; }
  .thread.line .day-mark::before { content: ""; left: calc(var(--rx) - var(--px) - 7px); top: calc(0.55rem - 1px); width: 14px; height: 2px; border: 0; border-radius: 1px; background: var(--rail-hi); }
  .thread.line .day-mark .stamp { color: var(--heading); }
  .your-turn { position: relative; margin: 1.4rem 0 0 calc(var(--cx) + 1.6rem); }
  .your-turn::before { content: ""; position: absolute; left: calc(-1.6rem - 1px); top: -1.4rem; height: 2.9rem; width: 2px; background: var(--rail); }
  .your-turn::after { content: ""; position: absolute; left: calc(-1.6rem - 8px); top: 1.2rem; width: 16px; height: 16px; box-sizing: border-box; border: 2px solid var(--brand); border-radius: 50%; background: var(--bg); box-shadow: 0 0 8px var(--brand); }
  .kids-talk.tray { margin: 2rem 0 0 calc(var(--cx) + 1.6rem); }
}
.thread { gap: 1.1rem; }
.bubble { padding: 0.65rem 0.95rem 0.75rem; }
.said-bot .bubble { background: var(--bubble); border: 1px solid color-mix(in srgb, var(--screen) 30%, var(--line)); border-radius: 4px 14px 14px 14px; }
.said-them .bubble { background: var(--bubble-them); border: 1px solid var(--plate-edge); border-left: 3px solid var(--steel); border-radius: var(--sq); }
.said-bot .said-by strong { color: var(--lit); }
.said-by { font-size: 0.75rem; font-weight: 500; letter-spacing: 0.02em; margin-bottom: 0.25rem; }
.said-by strong { font-weight: 500; }
.said-them .said-by { flex-direction: row; }
.said-text { font-size: 1.02rem; line-height: 1.55; max-width: 64ch; }
/* The family's mark is in their hand, steel, never the amber that means 'needs a look'. */
.said-them .avatar { color: var(--heading); background: var(--tray); box-shadow: inset 0 0 0 1.5px var(--steel); font-weight: 600; }
.kids-talk h2 { font-size: 1.2rem; }
@media (max-width: 40rem) {
  /* On the phone the line runs down the left gutter through her screens and ends at a lit ring
     above the box; the family's words sit right, hers left, each side leaving the other room. */
  .thread.line { --rx: 1.1rem; position: relative; margin-bottom: 0; padding: 0; }
  .thread.line::before { content: ""; position: absolute; z-index: 0; left: calc(var(--rx) - 1px); top: 0.4rem; bottom: calc(-1.4rem - 4px); width: 2px; background: var(--rail); }
  .thread .hang, .thread .day-mark { display: none; }
  .thread.line > li::before, .thread.line > li::after { content: none; }
  .thread.line > li { position: relative; z-index: 1; max-width: none; }
  .thread.line .said-bot { align-items: flex-start; }
  .thread.line .said-bot > .avatar { box-shadow: 0 0 0 3px var(--bg); }
  .thread.line .said-bot .bubble { margin-right: 2.5rem; }
  .thread.line .said-them .bubble { margin-left: 3rem; }
  .said-them .said-by { flex-direction: row; }
  .your-turn { position: relative; margin-top: 1.4rem; padding-top: 1.6rem; }
  .your-turn::after { content: ""; position: absolute; left: calc(1.1rem - 8px); top: 0; width: 16px; height: 16px; box-sizing: border-box; border: 2px solid var(--brand); border-radius: 50%; background: var(--bg); box-shadow: 0 0 8px var(--brand); }
}

/* ---- Ideas: head, tools beside the radar, and kind-tinted plates -------------------------- */
.scope { display: grid; gap: 0 1.25rem; margin: 0 0 1.25rem; }
.scope-tools > * { margin-bottom: 0.9rem; }
.scope-tools > :last-child { margin-bottom: 0; }
.scope .on-radar { margin: 0; }
@media (min-width: 64rem) {
  .scope.has-screen { grid-template-columns: minmax(0, 1fr) 23.5rem; align-items: start; }
  .on-radar .crt-tube { grid-template-columns: minmax(0, 1fr) 7rem; gap: 0.9rem; font-size: 1.3rem; }
  .on-radar .radar { width: 7rem; }
  .on-radar-count { font-size: 1.55rem; }
  .on-radar-line, .on-radar-more { font-size: 1.15rem; }
  .on-radar .radar-label { display: none; }
}
.capture > summary, .panel > summary { min-height: 2.75rem; align-items: center; }
details.panel.capture { padding: 0.35rem 1.1rem; }
details.panel.capture[open] { padding-bottom: 1.1rem; }
.filters.panel { padding: 0.85rem 1rem; gap: 0.75rem 0.75rem; }
.filters .field.wide { flex: 3 1 8.5rem; }
.scope .filters .field.wide { flex-basis: 100%; }
.tabs { padding: 0.2rem; background: var(--tray); border: 1px solid var(--plate-edge); border-radius: var(--r); }
.tabs a { min-height: 2.75rem; border-radius: 3px; }
.tabs a[aria-current="page"] { color: var(--heading); background: color-mix(in srgb, var(--steel) 15%, #151c22); box-shadow: inset 0 -2px 0 var(--steel); }
.count { margin: 0 0 0.75rem 0.1rem; font-size: 0.8rem; font-weight: 500; letter-spacing: 0; color: var(--label); }
.cards { gap: 0.6rem; padding: 0.75rem; background: var(--tray); border: 1px solid var(--tray-edge); border-radius: var(--sq); }
.cards > .card { --tint: 7%; position: relative; gap: 0.3rem; padding: 0.7rem 1rem 0.8rem; background: color-mix(in srgb, var(--accent) var(--tint), var(--plate)); border: 1px solid var(--plate-edge); border-radius: var(--sq); box-shadow: var(--shadow); }
.cards > .card:has(.kind-restaurant, .kind-activity, .kind-seasonal) { --tint: 4%; }
.cards .card .kind .icon { position: static; width: 1.7rem; height: 1.7rem; padding: 0.36rem; margin-right: 0.15rem; }
.cards .card .kind { gap: 0.5rem; }
.cards .card:has(h2 a):hover { background: color-mix(in srgb, var(--accent) calc(var(--tint) + 5%), var(--surface-2)); transform: none; border-color: color-mix(in srgb, var(--accent) 35%, var(--plate-edge)); box-shadow: var(--shadow), 0 0 30px -16px color-mix(in srgb, var(--accent) 60%, transparent); }
.card h2 a::after { border-radius: var(--sq); }
.card .meta { gap: 0.15rem 0.9rem; font-size: 0.86rem; }
.card-id { font-size: 0.72rem; color: var(--label); }
.cards .card-id { position: absolute; right: 0.8rem; top: 0.8rem; margin: 0; }

/* ---- To do page ---------------------------------------------------------------------------- */
.task-tools { display: grid; gap: 0 1rem; }
@media (min-width: 60rem) {
  .task-tools { grid-template-columns: minmax(0, 1fr) minmax(0, 1.25fr); align-items: start; }
  .task-tools:has(details[open]) { grid-template-columns: minmax(0, 1fr); }
}
.task-tools > .panel { margin-bottom: 1rem; }
.task-tools > details.panel { padding: 0.35rem 1.1rem; }
.task-tools > details.panel[open] { padding-bottom: 1.2rem; }
.task-tools .panel > summary .h2 { font: 600 1rem/1.3 var(--sans); font-stretch: 100%; letter-spacing: 0; word-spacing: 0; color: var(--ink); }
/* The list is a timetable on a board: the margin headed once, the count beside its head. */
.task-board.tray { padding: 0.95rem 1.1rem 1.05rem; }
.task-board, .task-line { --m: 6.6rem; --rx: calc(var(--m) + 0.6rem); --px: calc(var(--rx) + 1.15rem); }
.timetable-head { display: flex; align-items: baseline; margin: 0 0 0.65rem; }
.timetable-head .margin-legend { flex: none; margin: 0 calc(var(--px) - var(--m) + 0.2rem) 0 0; }
.task .tag.status-open { display: none; }
.footnote { margin: 0.9rem 0 0; }
.task-line { --ly: 1.55rem; --gap: 0.5rem; padding-bottom: 0; }
.task-line > li.task { display: flex; flex-flow: row wrap; align-items: center; gap: 0.2rem 1.25rem; margin: 0; padding: 0.35rem 0.9rem 0.35rem 0.3rem; }
.task-line > li.task > * { flex: 1 1 100%; }
.task-line > li.task > :not(.task-head):not(.hang) { margin-left: 3.25rem; }
.task-line > li.task > details.more { flex: 0 1 auto; order: 2; }
.task-line > li.task > details.more[open] { flex-basis: calc(100% - 3.25rem); }
.task-line > li.task > p.small { flex: 0 0 auto; order: 3; margin-left: auto; }
.task-line > li:not(.timed)::before { border-color: var(--rail-hi); }
.task-line > li.timed::before { border-color: color-mix(in srgb, var(--lemon) 70%, var(--rail-hi)); }
.task-line > li.task-done::before { background: var(--lit); border-color: var(--lit); }
.task-line .hang { top: calc(var(--ly) - 0.5lh); }
.task-head { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 0 0.5rem; }
.task-head .tick { margin: 0; }
.task-head .task-box { margin: 0 0.8rem; width: 1.15rem; height: 1.15rem; border-width: 1.5px; border-radius: 3px; }
.task-done .task-box { background: var(--lit); border-color: var(--lit); box-shadow: none; }
.task h2 { margin: 0; }
.task h2 .muted { font: 500 0.78rem var(--mono); color: var(--label); }
.task-head .facts { display: flex; align-items: center; gap: 0.4rem 0.9rem; margin: 0; font-size: 0.86rem; }
