.task p.small { font-size: 0.85rem; }
.task .more summary { font-size: 0.9rem; font-weight: 500; color: var(--ink-2); }
.tag { border-radius: 3px; }
.status-open { color: var(--lemon); background: rgb(247 220 120 / 0.08); }

@media (max-width: 40rem) {
  .margin-legend { display: none; }
  .due-word { display: inline; }
  .checklist { --m: 0rem; --rx: 0.45rem; --px: 1.55rem; }
  .checklist > li { grid-template: "k s f" auto "k w f" auto / auto minmax(0, 1fr) auto; }
  .checklist .hang { position: static; grid-area: s; width: auto; text-align: left; }
  .checklist .tick-form, .checklist .task-box { grid-area: k; }
  .checklist .checklist-body { grid-area: w; }
  .checklist .facts { grid-area: f; }
  .checklist > li:not(.timed) .checklist-body { grid-row: 1 / 3; }
  .task-line { --m: 0rem; --rx: 0.45rem; --px: 1.55rem; }
  .task-line .hang { position: static; order: -1; width: auto; text-align: left; margin: 0.25rem 0 -0.2rem 3.25rem; }
  .task-head .facts { grid-column: 2 / -1; flex-wrap: wrap; }
  .task-head { grid-template-columns: auto minmax(0, 1fr); }
  .scope-tools .tabs { margin-top: 0; }
}

/* ---- Plans --------------------------------------------------------------------------------- */
.month-board { padding: 1rem 1.1rem 0.5rem; }
.month-head { margin-bottom: 0.4rem; }
.month-nav .button { min-height: 2.75rem; }
table.month.panel { margin: 0; padding: 0; background: none; border: 0; box-shadow: none; }
table.month th { padding: 0.5rem 0.55rem 0.55rem; font-size: 0.72rem; color: var(--label); }
table.month td { height: 4.9rem; padding: 0.35rem 0.4rem; border-color: #1d252b; }
table.month td:nth-child(n + 6) { background: rgb(167 196 216 / 0.035); }
table.month td.outside { background: rgb(0 0 0 / 0.25); }
table.month time { width: auto; height: auto; padding: 0.1rem 0.25rem; font: 500 0.82rem/1.2 var(--mono); border-radius: 0; }
table.month td.today { background: color-mix(in srgb, var(--steel) 9%, transparent); box-shadow: inset 0 2px 0 var(--steel); }
table.month td.today time { color: var(--heading); background: none; box-shadow: none; }
.now-lamp { display: inline-block; width: 8px; height: 8px; margin-left: 0.25rem; vertical-align: 0.05rem; border-radius: 50%; background: var(--brand); box-shadow: 0 0 8px var(--brand); animation: breathe 3.2s ease-in-out infinite; }
/* Each plan on the month is a stop: a plate with its lamp, a cyan ring to come, lit sage once
   past, and today's the breathing now lamp. Days gone by step back. */
.event { position: relative; margin-top: 0.3rem; padding: 0.3rem 0.45rem 0.32rem 1.25rem; font-size: 0.8rem; background: var(--plate); border: 1px solid var(--plate-edge); border-radius: var(--sq); box-shadow: var(--shadow); }
.event::before { content: ""; position: absolute; left: 0.42rem; top: calc(0.3rem + 0.65lh - 4px); width: 8px; height: 8px; box-sizing: border-box; background: var(--tray); border: 1.5px solid var(--cyan); border-radius: 50%; }
.event small { font-size: 0.72rem; color: var(--label); }
.event.from-google { border-style: dashed; }
table.month tr:has(~ tr td.today) .event::before, table.month td:has(~ td.today) .event::before { background: var(--lit); border-color: var(--lit); }
table.month tr:has(~ tr td.today) :is(time, .event), table.month td:has(~ td.today) :is(time, .event) { color: var(--faint); }
table.month td.today .event::before { background: var(--brand); border-color: var(--brand); box-shadow: 0 0 6px var(--brand); animation: breathe 3.2s ease-in-out infinite; }
.month-list .event { padding-left: 1.25rem; }
.month-list li.today strong { color: var(--heading); }
.month-list li.today .event::before { background: var(--brand); border-color: var(--brand); box-shadow: 0 0 6px var(--brand); }
.plan-line { --lc: var(--cyan); }
.plan-line .line.agenda { --m: 4.4rem; --rx: calc(var(--m) + 0.7rem); --px: calc(var(--rx) + 1.2rem); --ly: 1.3rem; }
.plan-line .line > li { padding: 0.6rem 0.9rem; background: var(--plate); border: 1px solid var(--plate-edge); border-radius: var(--sq); }
.plan-line .line .chip { position: absolute; left: calc(-1 * var(--px)); top: 0.45rem; width: calc(var(--m) - 0.2rem); justify-content: end; }
.plan-line > h2 { margin: 0 0 1rem; }
.plan-line .agenda-body { padding: 0; background: none; border: 0; box-shadow: none; }
.is-today .rel { color: var(--heading); background: none; }
.is-today .rel::before { content: ""; display: inline-block; width: 7px; height: 7px; margin: 0 0.4rem 0.05rem 0; border-radius: 50%; background: var(--brand); box-shadow: 0 0 6px var(--brand); }
.chip.is-today .chip-mon { color: var(--cyan); }
.line > li.is-today::before { background: var(--brand); border-color: var(--brand); box-shadow: 0 0 0 3px var(--tray), 0 0 8px var(--brand); }

/* ---- Status -------------------------------------------------------------------------------- */
.monitors { gap: 1rem; margin-bottom: 1.5rem; }
.monitors > .panel.tray { margin: 0; align-self: stretch; }
.lights { --rx: 0.975rem; --px: 2.2rem; --ly: 1.3rem; --gap: 0.4rem; }
.lights.line > li::after { content: none; }
.monitors > .tray:first-child .lights.line > li:not(:last-child)::after { content: ""; }
.monitors > .tray:first-child .lights.line::before { content: ""; position: absolute; z-index: 1; left: calc(var(--rx) - 1px); top: 0; width: 2px; height: var(--ly); background: var(--rail); }
.lights > li { display: block; padding: 0.55rem 0.8rem 0.6rem; }
.lights > li > .light { position: absolute; z-index: 2; left: calc(var(--rx) - var(--px) - 6px); top: calc(var(--ly) - 6px); width: 12px; height: 12px; margin: 0; box-sizing: border-box; background: var(--tray); }
.lights > li::before { content: none; }
.lights .light.on { background: var(--brand); border: 0; box-shadow: 0 0 0 3px var(--tray), 0 0 7px var(--brand); }
.lights .light.off { border: 2px solid var(--red); }
.lights .light.part { border: 2px solid var(--amber); background: linear-gradient(90deg, var(--amber) 50%, var(--tray) 50%); }
.lights strong { color: var(--heading); font-weight: 600; }
.lights .muted { font-size: 0.875rem; }
.spend .crt { max-width: 26rem; }
.activity { --m: 6.9rem; --rx: calc(var(--m) + 0.6rem); --px: calc(var(--rx) + 1.1rem); --ly: 1.3rem; }
.activity li + li { border-top: 0; }
.panel.attention { border: 1px solid color-mix(in srgb, var(--red) 45%, var(--line)); }
.page-status main > section.panel:not(.attention) { background: var(--tray); border: 1px solid var(--tray-edge); border-radius: var(--sq); box-shadow: none; }
.panel > h2 > .icon { box-sizing: content-box; flex: none; width: 1.12rem; height: 1.12rem; padding: 0.415rem; color: var(--rk, var(--steel)); }
.trouble.panel { background-color: #131612; border: 1px solid #644e29; }

/* ---- Settings ------------------------------------------------------------------------------ */
.section-cards { gap: 0.6rem; padding: 0.75rem; background: var(--tray); border: 1px solid var(--tray-edge); border-radius: var(--sq); }
.section-card.panel { gap: 0.8rem; padding: 1rem 1.1rem; background: var(--plate); border: 1px solid var(--plate-edge); border-radius: var(--sq); box-shadow: var(--shadow); }
.section-card:hover { background: var(--surface-2); border-color: color-mix(in srgb, var(--steel) 35%, var(--plate-edge)); box-shadow: var(--shadow), 0 0 26px -16px color-mix(in srgb, var(--steel) 70%, transparent); }
.section-card.look { border-color: #644e29; }
.section-icon { width: 1.6rem; height: 1.45rem; color: var(--steel); background: none; border: 0; border-radius: 0; box-shadow: none; }
.section-icon .icon { width: 1.3rem; height: 1.3rem; stroke-width: 1.8; }
.section-icon.presence { width: 1.6rem; height: 1.6rem; margin-top: -0.05rem; border: 1px solid rgb(109 255 156 / 0.32); border-radius: 6px; }
.section-what strong { font-weight: 600; color: var(--heading); }
.settings-nav .line { --rx: 0.45rem; --px: 1.45rem; --ly: 1.375rem; --gap: 0.1rem; gap: var(--gap); padding-left: var(--px); }
.settings-nav .line > li::before { border-color: var(--rail-hi); }
.settings-nav li:has([aria-current])::before { background: var(--steel); border-color: var(--steel); }
.settings-nav a { min-height: 2.75rem; border-radius: 3px; }
.settings-nav a[aria-current="page"] { color: var(--heading); background: color-mix(in srgb, var(--steel) 15%, #141b20); border-color: #0000; box-shadow: inset 2px 0 0 var(--steel); }
.save-bar { border-radius: var(--sq); }

/* The steps of setting up: amber rings for what waits, lit sage for what is done, the phosphor
   on the step to take next. */
.setup-list { --rx: 0.45rem; --px: 1.6rem; --ly: 1.85rem; --gap: 0.5rem; --lc: var(--amber); }
.setup-list > li.panel { border-radius: var(--sq); }
.setup-list > .done::before { background: var(--lit); border-color: var(--lit); }
.setup-list > .now::before { border-color: var(--brand); box-shadow: 0 0 7px var(--brand); }
.setup-list .number { border-radius: 3px; }

/* ---- Sign in and the lost page: the case beside a short line ------------------------------ */
@media (min-width: 52rem) {
  .signin, .lost { display: grid; grid-template-columns: 22rem minmax(0, 23rem); gap: 3rem; align-items: center; max-width: 48rem; margin: 0 auto; text-align: left; }
  .signin .crt, .lost .crt { margin: 0; }
}
.signin-line, .lost-line { position: relative; padding-left: 2.2rem; }
.signin-line::before, .lost-line::before { content: ""; position: absolute; left: calc(0.45rem - 1px); top: 0.6rem; bottom: 1.4rem; width: 2px; background: var(--rail); }
.lost-line::before { bottom: 1.375rem; }
.lost-line .end { display: flex; margin: 1.3rem 0 0; }
.lost-line .end .button { min-height: 2.75rem; margin: 0; }
.signin-line::after, .lost-line::after { content: ""; position: absolute; z-index: 1; left: calc(0.45rem - 6px); top: 0.6rem; width: 12px; height: 12px; box-sizing: border-box; background: var(--bg); border: 2px solid var(--steel); border-radius: 50%; }
.line-form { position: relative; }
.line-form::before { content: ""; position: absolute; z-index: 1; left: calc(-1.75rem - 6px); bottom: 1.33rem; width: 12px; height: 12px; box-sizing: border-box; background: var(--bg); border: 2px solid var(--brand); border-radius: 50%; box-shadow: 0 0 6px var(--brand); }
.lost-line .end { position: relative; }
.lost-line .end::before { content: ""; position: absolute; z-index: 1; left: calc(-1.75rem - 6px); top: calc(50% - 6px); width: 12px; height: 12px; box-sizing: border-box; background: var(--bg); border: 2px solid var(--red); border-radius: 50%; }
.signin h1 { font-size: 2.1rem; }
.signin .panel, .signin { box-shadow: none; }

/* ---- Foot ---------------------------------------------------------------------------------- */
.foot { border-top: 2px solid #1c2429; }
.foot-mark { color: var(--ink-2); }
h3 { color: var(--label); }
.data caption, table.month th { color: var(--label); }
